<template>
  <section>
    <p class="operating-flow-note">先核对目的国家和剩余需求，再按供应商填写本次拆分数量与采购单价。可分多次拆分，未拆部分继续保留。</p>
    <div class="filter-bar"><el-input v-model="search" placeholder="订货单号 / 国家" clearable @keyup.enter="load"/><el-button type="primary" plain @click="load">查询</el-button></div>
    <el-alert v-if="error" :title="error" type="error" :closable="false"/>
    <div class="table-scroll"><el-table :data="rows" v-loading="loading" border empty-text="暂无已提交的运营订货单"><el-table-column label="运营订货单号" min-width="170"><template #default="{row}"><el-button link type="primary" @click="open(row)">{{row.number}}</el-button></template></el-table-column><el-table-column prop="country_name" label="国家" min-width="120"/><el-table-column prop="order_date" label="日期" width="120"/><el-table-column prop="total_quantity" label="订货数量" width="120" align="right"/><el-table-column prop="version" label="版本" width="80"/><el-table-column label="操作" width="100"><template #default="{row}"><el-button size="small" @click="open(row)">拆分</el-button></template></el-table-column></el-table></div>
    <el-pagination class="pagination" layout="total, prev, pager, next" :total="total" :current-page="page" :page-size="20" @current-change="changePage"/>
    <el-drawer v-model="drawer" :title="detail?.number ? `拆分 ${detail.number}` : '运营订货单拆分'" size="min(1000px, 96vw)"><div v-if="detail">
      <el-descriptions :column="2" border><el-descriptions-item label="国家">{{detail.country_name}}</el-descriptions-item><el-descriptions-item label="版本">v{{detail.version}}</el-descriptions-item><el-descriptions-item label="来源">{{({new_goods:'新货订货',cycle:'周期订货',season:'季节订货'})[detail.source_kind]||detail.source_kind}}</el-descriptions-item><el-descriptions-item label="状态">{{({draft:'草稿',submitted:'已提交',cancelled:'已取消'})[detail.status]||detail.status}}</el-descriptions-item></el-descriptions>
      <div class="split-form"><el-form-item label="供应商 *"><el-select v-model="form.supplier_id" filterable remote :remote-method="searchSuppliers" :loading="optionLoading" placeholder="搜索采购供应商" @visible-change="openOptions"><el-option v-for="item in suppliers" :key="item.id" :label="`${item.code ? item.code+' · ' : ''}${item.name}`" :value="item.id"/></el-select></el-form-item><el-form-item label="备注单号"><el-input v-model="form.reference_number" maxlength="120"/></el-form-item></div>
      <el-form-item label="采购备注"><el-input v-model="form.notes" type="textarea" :rows="2"/></el-form-item>
      <div class="table-scroll"><el-table :data="lines" border><el-table-column label="商品图片" width="110"><template #default="{row}"><OperatingProductImageV2 v-if="row.sku_id" :sku-id="row.sku_id" :source="row.product_details?.image_url || ''" procurement /></template></el-table-column><el-table-column label="SKU" min-width="190"><template #default="{row}"><DocumentSkuV2 :sku="row.sku" :legacy-sku-code="row.legacy_sku_code"/></template></el-table-column><el-table-column prop="product_name" label="商品" min-width="170"/><el-table-column prop="quantity" label="运营订货量" width="120" align="right"/><el-table-column prop="allocated_quantity" label="已分配" width="100" align="right"/><el-table-column prop="remaining_quantity" label="剩余可分" width="110" align="right"/><el-table-column label="本次拆分 *" width="160"><template #default="{row}"><el-input-number v-model="row.split_quantity" :min="0" :max="Number(row.remaining_quantity||0)" :precision="0" :controls="false" :disabled="!canManage || detail.status!=='submitted'"/></template></el-table-column><el-table-column label="采购单价（选填）" width="170"><template #default="{row}"><el-input-number v-model="row.unit_price" :min="0" :precision="4" :controls="false" placeholder="可留空" :disabled="!canManage || detail.status!=='submitted'"/></template></el-table-column></el-table></div>
      <el-alert v-if="formError" :title="formError" type="error" :closable="false"/><p class="muted">一次拆分只对应一个供应商；可部分拆分，数量不能超过每行剩余可分数量。</p>
    </div><template #footer><div class="actions"><el-button @click="drawer=false">关闭</el-button><el-button v-if="canManage" type="primary" :loading="busy" :disabled="detail?.status!=='submitted'" @click="split">创建采购草稿</el-button></div></template></el-drawer>
  </section>
</template>
<script setup>
import { computed, onMounted, reactive, ref } from 'vue';
import { ElMessage } from 'element-plus';
import DocumentSkuV2 from './DocumentSkuV2.vue';
import OperatingProductImageV2 from './OperatingProductImageV2.vue';
import { useAuthStore } from '../../stores/auth';
import * as api from '../../api/operatingOrdersV2';
import * as supplyApi from '../../api/supplyChainV2';
const props=defineProps({canView:Boolean,canManage:Boolean});const emit=defineEmits(['open-order']);const auth=useAuthStore();const canManage=computed(()=>props.canManage&&!auth.authorizationStale&&auth.hasPermission('supply.v2.manage'));
const rows=ref([]),total=ref(0),page=ref(1),search=ref(''),loading=ref(false),busy=ref(false),error=ref(''),drawer=ref(false),detail=ref(null),lines=ref([]),formError=ref(''),suppliers=ref([]),optionLoading=ref(false);const form=reactive({supplier_id:null,reference_number:'',notes:''});let seq=0;const actions=new Map();const fail=r=>r?.data?.detail||r?.message||'请求失败，请重试。';
async function load(){if(!props.canView)return;loading.value=true;error.value='';try{const r=await api.fetchSubmittedProcurementOrders({search:search.value.trim(),limit:20,offset:(page.value-1)*20});if(!r?.success){error.value=fail(r);return}rows.value=Array.isArray(r.data)?r.data:r.data?.results||[];total.value=Number(r.count??r.data?.count??0)}finally{loading.value=false}}
function changePage(v){page.value=v;load()}async function searchSuppliers(search=''){const current=++seq;optionLoading.value=true;try{const r=await supplyApi.fetchSupplyOptions({kind:'suppliers',search,limit:100,offset:0});if(current!==seq)return;if(!r?.success){formError.value=fail(r);return}suppliers.value=Array.isArray(r.data)?r.data:r.data?.results||[]}finally{if(current===seq)optionLoading.value=false}}function openOptions(open){if(open&&!suppliers.value.length)searchSuppliers('')}
async function open(row){const r=await api.fetchSubmittedProcurementOrder(row.id);if(!r?.success){ElMessage.error(fail(r));return}detail.value=r.data;lines.value=(r.data.lines||[]).map(l=>({...l,split_quantity:0,unit_price:null}));Object.assign(form,{supplier_id:null,reference_number:'',notes:''});formError.value='';drawer.value=true}
async function split(){if(!canManage.value||!detail.value||detail.value.status!=='submitted'||busy.value)return;formError.value='';if(!form.supplier_id){formError.value='请选择一个供应商。';return}const chosen=lines.value.filter(l=>Number(l.split_quantity)>0);if(!chosen.length){formError.value='至少填写一行大于 0 的拆分数量。';return}if(chosen.some(l=>!Number.isInteger(Number(l.split_quantity))||Number(l.split_quantity)>Number(l.remaining_quantity))){formError.value='拆分数量必须为正整数，且不超过该行剩余数量。';return}const data={expected_version:detail.value.version,supplier_id:form.supplier_id,reference_number:form.reference_number.trim(),notes:form.notes,lines:chosen.map(l=>({operating_line_id:l.id,quantity:Number(l.split_quantity),...(l.unit_price===null||l.unit_price===''?{}:{unit_price:Number(l.unit_price)})}))};const fingerprint=JSON.stringify(data),slot=`split-${detail.value.id}`;let action=actions.get(slot);if(!action||action.fingerprint!==fingerprint){action={fingerprint,key:supplyApi.createIdempotencyKey()};actions.set(slot,action)}busy.value=true;try{const r=await api.splitOperatingOrder(detail.value.id,data,action.key);if(!r?.success){formError.value=`${fail(r)}${!r?.http_status||r.http_status>=500?' 结果未确认，可用相同内容安全重试。':''}`;if(r?.http_status&&r.http_status<500)actions.delete(slot);return}actions.delete(slot);ElMessage.success('采购草稿已创建。');drawer.value=false;emit('open-order',r.data.purchase_order);await load()}catch(e){formError.value=`${e.message||'网络异常'}，结果未确认，可用相同内容安全重试。`}finally{busy.value=false}}
onMounted(load);
</script>
<style scoped>.filter-bar,.actions{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.filter-bar{margin:12px 0 18px}.filter-bar>.el-input{width:min(340px,100%)}.table-scroll{overflow-x:auto}.pagination{margin-top:16px}.split-form{display:grid;grid-template-columns:1fr 1fr;gap:0 16px}.split-form :deep(.el-select){width:100%}.muted{color:#64748b;font-size:13px}.actions{justify-content:flex-end}@media(max-width:680px){.split-form{grid-template-columns:1fr}.actions{justify-content:flex-start}}</style>

<style scoped>
.operating-flow-note{font-size:14px;color:#475569;line-height:1.8;margin:8px 0 18px;padding:12px 16px;background:#f1f5fb;border-left:3px solid #2563eb}
</style>
